  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/books.py": "\"\"\"\nModule for managing books in the Mini Library System.\n\nThis module provides functionality to list books and update their quantities.\n\"\"\"\n\nbooks = {\n    \"1984\": 3,\n    \"Brave New World\": 2,\n    \"Python 101\": 5\n}\n\n\ndef list_books():\n    \"\"\"\n    List all books and their available quantities.\n\n    Prints each book's title along with the number of available copies.\n    \"\"\"\n    for book, qty in books.items():\n        print(f\"{book}: {qty} copies\")\n\n\ndef update_book(book_name, qty):\n    \"\"\"\n    Update the quantity of a book in the inventory.\n\n    Args:\n        book_name (str): The title of the book to update.\n        qty (int): The quantity to add (can be negative).\n\n    Raises:\n        ValueError: If the update would result in a negative quantity.\n    \"\"\"\n    if books[book_name] + qty < 0:\n        raise ValueError(f\"Cannot update {book_name}: quantity would become negative\")\n    books[book_name] += qty\n",
