  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/borrow.py": "\"\"\"\nModule for managing book borrowing and returning in the Mini Library System.\n\nThis module provides functionality to borrow and return books, updating both\nbook quantities and user records.\n\"\"\"\nfrom books import books, update_book\nfrom users import users\n\n\ndef borrow_book(user, book_name):\n    \"\"\"\n    Borrow a book from the library.\n\n    Args:\n        user (str): The name of the user borrowing the book.\n        book_name (str): The title of the book to borrow.\n\n    Prints a message indicating whether the book was successfully borrowed or not.\n    \"\"\"\n    if books[book_name] > 0:\n        users[user].append(book_name)\n        update_book(book_name, -1)\n        print(f\"{user} borrowed {book_name}\")\n    else:\n        print(f\"{book_name} is not available\")\n\n\ndef return_book(user, book_name):\n    \"\"\"\n    Return a book to the library.\n\n    Args:\n        user (str): The name of the user returning the book.\n        book_name (str): The title of the book to return.\n\n    Prints a message confirming the book was returned.\n    \"\"\"\n    update_book(book_name, 1)\n    if book_name in users[user]:\n        users[user].remove(book_name)\n    print(f\"{user} returned {book_name}\")\n",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/sandbox/users.py": "\"\"\"\nModule for managing users in the Mini Library System.\n\nThis module provides functionality to add and list users, along with tracking their borrowed books.\n\"\"\"\n\nusers = {}\n\n\ndef add_user(name):\n    \"\"\"\n    Add a new user to the system.\n\n    Args:\n        name (str): The name of the user to add.\n        \n    Raises:\n        KeyError: If the name is not a string or is None.\n    \"\"\"\n    if not isinstance(name, str):\n        raise KeyError(\"User name must be a string\")\n    if name in users:\n        return\n    users[name] = []\n\n\ndef list_users():\n    \"\"\"\n    List all users and their borrowed books.\n\n    Prints each user's name along with the list of books they have borrowed.\n    \"\"\"\n    if not users:\n        return\n    for name, borrowed in users.items():\n        print(f\"{name}: {borrowed}\")\n",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/sandbox/books.py": "\"\"\"\nModule for managing books in the Mini Library System.\n\nThis module provides functionality to list books and update their quantities.\n\"\"\"\n\nbooks = {\n    \"1984\": 3,\n    \"Brave New World\": 2,\n    \"Python 101\": 5\n}\n\n\ndef list_books():\n    \"\"\"\n    List all books and their available quantities.\n\n    Prints each book's title along with the number of available copies.\n    \"\"\"\n    if not books:\n        return\n    for book, qty in books.items():\n        print(f\"{book}: {qty} copies\")\n\n\ndef update_book(book_name, qty):\n    \"\"\"\n    Update the quantity of a book in the inventory.\n\n    Args:\n        book_name (str): The title of the book to update.\n        qty (int): The quantity to add (can be negative).\n\n    Raises:\n        ValueError: If the update would result in a negative quantity.\n        TypeError: If the quantity is not an integer.\n    \"\"\"\n    if not isinstance(qty, int):\n        raise TypeError(\"Quantity must be an integer\")\n    if book_name not in books:\n        raise KeyError(f\"Book '{book_name}' not found\")\n    if books[book_name] + qty < 0:\n        raise ValueError(f\"Cannot update {book_name}: quantity would become negative\")\n    books[book_name] += qty\n",
