{
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/accounts.py": "\"\"\"\nModule for managing bank accounts.\nProvides the BankAccount class with basic deposit and withdraw functionality.\n\"\"\"\n\nclass BankAccount:\n    \"\"\"\n    A class representing a bank account.\n\n    Attributes:\n        owner (str): The name of the account owner.\n        balance (float): The current balance of the account.\n    \"\"\"\n\n    def __init__(self, owner, balance):\n        \"\"\"\n        Initialize a BankAccount instance.\n\n        Args:\n            owner (str): The name of the account owner.\n            balance (float): The initial balance of the account.\n\n        Raises:\n            TypeError: If owner is not a string or balance is not numeric.\n        \"\"\"\n        if not isinstance(owner, str):\n            raise TypeError(\"Owner must be a string\")\n        if not isinstance(balance, (int, float)):\n            raise TypeError(\"Balance must be numeric\")\n        self.owner = owner\n        self.balance = float(balance)\n\n    def deposit(self, amount):\n        \"\"\"\n        Deposit money into the account.\n\n        Args:\n            amount (float): The amount to deposit.\n\n        Raises:\n            TypeError: If amount is not numeric.\n        \"\"\"\n        if not isinstance(amount, (int, float)):\n            raise TypeError(\"Amount must be numeric\")\n        self.balance += amount\n\n    def withdraw(self, amount):\n        \"\"\"\n        Withdraw money from the account.\n\n        Args:\n            amount (float): The amount to withdraw.\n\n        Raises:\n            ValueError: If the account has insufficient funds for the withdrawal.\n            TypeError: If amount is not numeric.\n        \"\"\"\n        if not isinstance(amount, (int, float)):\n            raise TypeError(\"Amount must be numeric\")\n        if amount < 0 or amount > self.balance:\n            raise ValueError(\"Insufficient funds for withdrawal\")\n        self.balance -= amount\n",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/transactions.py": "\"\"\"\nModule for handling bank account transactions.\nProvides functions to deposit and withdraw money from BankAccount instances.\n\"\"\"\n\nfrom sandbox.accounts import BankAccount\n\ndef deposit(account: BankAccount, amount):\n    \"\"\"\n    Deposit money into a bank account.\n\n    Args:\n        account (BankAccount): The bank account to deposit into.\n        amount (float): The amount to deposit.\n\n    Raises:\n        TypeError: If amount is not numeric.\n    \"\"\"\n    if not isinstance(amount, (int, float)):\n        raise TypeError(\"Amount must be numeric\")\n    account.deposit(amount)\n\ndef withdraw(account: BankAccount, amount):\n    \"\"\"\n    Withdraw money from a bank account.\n\n    Args:\n        account (BankAccount): The bank account to withdraw from.\n        amount (float): The amount to withdraw.\n\n    Raises:\n        ValueError: If the account has insufficient funds for the withdrawal.\n        TypeError: If amount is not numeric.\n    \"\"\"\n    if not isinstance(amount, (int, float)):\n        raise TypeError(\"Amount must be numeric\")\n    account.withdraw(amount)\n",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/utils.py": "\"\"\"\nUtility module for banking operations.\nProvides helper functions for printing transaction information.\n\"\"\"\n\nfrom sandbox.accounts import BankAccount\n\ndef print_transaction(account, amount, action):\n    \"\"\"\n    Print transaction details.\n\n    Args:\n        account (BankAccount): The bank account involved in the transaction.\n        amount (float): The transaction amount.\n        action (str): The type of transaction (e.g., 'deposit', 'withdraw').\n    \"\"\"\n    print(f\"{action} {amount} for {account.owner}\n\")",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/main.py": "\"\"\"\nMain module for demonstrating bank account operations.\nCreates a bank account and performs sample transactions.\n\"\"\"\n\nfrom sandbox.accounts import BankAccount\nfrom sandbox.transactions import deposit, withdraw\n\ndef main():\n    \"\"\"\n    Demonstrate bank account operations.\n    Creates an account, performs deposits and withdrawals, and prints the balance.\n    \"\"\"\n    # Create account\n    account = BankAccount(\"Alice\", 100)\n\n    # Transactions\n    deposit(account, 50)\n    try:\n        withdraw(account, 200)  # Should fail due to insufficient funds\n    except ValueError as e:\n        print(f\"Withdrawal failed: {e}\")\n    \n    withdraw(account, 30)\n    print(account.balance)\n\nif __name__ == \"__main__\":\n    main()",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/tests/test_utils.py": "import pytest\nfrom sandbox.accounts import BankAccount\nfrom sandbox.utils import print_transaction\nfrom io import StringIO\nimport sys\n\n\ndef test_print_transaction(capsys):\n    account = BankAccount(\"Alice\", 100.0)\n    print_transaction(account, 50.0, \"deposit\")\n    captured = capsys.readouterr()\n    assert captured.out == \"deposit 50.0 for Alice\n\"\n\n\ndef test_print_transaction_withdraw(capsys):\n    account = BankAccount(\"Bob\", 200.0)\n    print_transaction(account, 30.0, \"withdraw\")\n    captured = capsys.readouterr()\n    assert captured.out == \"withdraw 30.0 for Bob\n\"",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/tests/test_accounts.py": "import pytest\nfrom sandbox.accounts import BankAccount\n\n\ndef test_bank_account_initialization():\n    account = BankAccount(\"Alice\", 100.0)\n    assert account.owner == \"Alice\"\n    assert account.balance == 100.0\n\n\ndef test_bank_account_initialization_with_integer_balance():\n    account = BankAccount(\"Bob\", 50)\n    assert account.balance == 50\n\n\ndef test_bank_account_initialization_invalid_owner():\n    with pytest.raises(TypeError, match=\"Owner must be a string\"):\n        BankAccount(123, 100.0)\n\n\ndef test_bank_account_initialization_invalid_balance():\n    with pytest.raises(TypeError, match=\"Balance must be numeric\"):\n        BankAccount(\"Alice\", \"100\")\n\n\ndef test_deposit_valid_amount():\n    account = BankAccount(\"Alice\", 100.0)\n    account.deposit(50.0)\n    assert account.balance == 150.0\n\n\ndef test_deposit_invalid_amount():\n    account = BankAccount(\"Alice\", 100.0)\n    with pytest.raises(TypeError, match=\"Amount must be numeric\"):\n        account.deposit(\"50\")\n\n\ndef test_withdraw_valid_amount():\n    account = BankAccount(\"Alice\", 100.0)\n    account.withdraw(50.0)\n    assert account.balance == 50.0\n\n\ndef test_withdraw_insufficient_funds():\n    account = BankAccount(\"Alice\", 100.0)\n    with pytest.raises(ValueError, match=\"Insufficient funds for withdrawal\"):\n        account.withdraw(150.0)\n\n\ndef test_withdraw_negative_amount():\n    account = BankAccount(\"Alice\", 100.0)\n    with pytest.raises(ValueError, match=\"Insufficient funds for withdrawal\"):\n        account.withdraw(-10.0)\n\n\ndef test_withdraw_invalid_amount():\n    account = BankAccount(\"Alice\", 100.0)\n    with pytest.raises(TypeError, match=\"Amount must be numeric\"):\n        account.withdraw(\"50\")",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/tests/test_transactions.py": "import pytest\nfrom sandbox.accounts import BankAccount\nfrom sandbox.transactions import deposit, withdraw\n\n\ndef test_deposit_function():\n    account = BankAccount(\"Alice\", 100.0)\n    deposit(account, 50.0)\n    assert account.balance == 150.0\n\n\ndef test_deposit_function_invalid_amount():\n    account = BankAccount(\"Alice\", 100.0)\n    with pytest.raises(TypeError, match=\"Amount must be numeric\"):\n        deposit(account, \"50\")\n\n\ndef test_withdraw_function():\n    account = BankAccount(\"Alice\", 100.0)\n    withdraw(account, 50.0)\n    assert account.balance == 50.0\n\n\ndef test_withdraw_function_insufficient_funds():\n    account = BankAccount(\"Alice\", 100.0)\n    with pytest.raises(ValueError, match=\"Insufficient funds for withdrawal\"):\n        withdraw(account, 150.0)\n\n\ndef test_withdraw_function_invalid_amount():\n    account = BankAccount(\"Alice\", 100.0)\n    with pytest.raises(TypeError, match=\"Amount must be numeric\"):\n        withdraw(account, \"50\")",
